#!/usr/bin/env bash
# Detector `ledger-entry-names-artefact` for [R:features-ledger-names-its-artefact], generated by relearn from the rule file.
# Edit the rule, never this script: `relearn verify` reports a hand edit.
# Engine: sections. Event: Claude Code PreToolUse on Write, and PostToolUse on Edit|MultiEdit
# (warns only after an edit: the edit has happened).
# Exit 2 blocks, and stderr is the reason Claude reads. Exit 0 allows.
# Any other exit is this script failing: reported, never a block.
set -uo pipefail
export LC_ALL=C

name='ledger-entry-names-artefact'
tag='R:features-ledger-names-its-artefact'
message='A behaviour-ledger entry names no enforcing artefact. Every level-3 entry carries an Enforced by line naming the type, property test or unit test that holds it, or says NOTHING YET and goes to TODO.md. An Enforced by line placed under the next heading belongs to that entry, not this one.'
files_ere='((^|/)([^/]+/)*FEATURES\.md$)'
exclude_ere='((^|/)([^/]+/)*rules/[^/]*\.md$)|((^|/)([^/]+/)*hooks-pack/.*$)|((^|/)([^/]+/)*repo-pack/.*$)|((^|/)([^/]+/)*hooks/relearn/.*$)'

fail() {
  printf '[%s] %s; the detector did not run.\n' "$name" "$1" >&2
  exit 1
}
command -v jq >/dev/null 2>&1 || fail "jq is not on PATH"

input="$(cat)"
tool_name="$(jq -r '.tool_name // ""' <<<"$input")" || fail "the payload is not JSON"
case "$tool_name" in Write|Edit|MultiEdit) ;; *) exit 0 ;; esac
file_path="$(jq -r '.tool_input.file_path // ""' <<<"$input")" || fail "the payload has no readable file_path"
file_path="${file_path//\\//}"
[ -n "$file_path" ] || exit 0

# Scope: one ERE per list, compiled by relearn from the rule's globs.
printf '%s\n' "$file_path" | grep -qE -- "$files_ere"
case $? in 0) ;; 1) exit 0 ;; *) fail "grep could not read the files pattern" ;; esac
printf '%s\n' "$file_path" | grep -qE -- "$exclude_ere"
case $? in 0) exit 0 ;; 1) ;; *) fail "grep could not read the exclude pattern" ;; esac

require='[Ee]nforced by|NOTHING YET'
level=3
work="$(mktemp -d)" || fail "no scratch directory"
trap 'rm -rf "$work"' EXIT

sections_judge() {
  grep -nE -- "$2" "$1" > "$work/req.raw"
  case $? in 0|1) ;; *) return 2 ;; esac
  cut -d: -f1 "$work/req.raw" > "$work/req" || return 2
  RL_LEVEL="$3" awk '
BEGIN { lvl = ENVIRON["RL_LEVEL"] + 0; hits = 0 }
FILENAME == ARGV[1] { ok[$1] = 1; next }
{
  line = $0; sub(/\r$/, "", line)
  fence = (substr(line, 1, 3) == "```" || substr(line, 1, 3) == "~~~")
  if (!infence && !fence) {
    n = 0; while (n < 7 && substr(line, n + 1, 1) == "#") n++
    c = substr(line, n + 1, 1)
    if (n >= 1 && n <= 6 && (c == " " || c == "\t" || c == "") && n <= lvl) {
      if (open && !sat) { print head; hits++ }
      open = (n == lvl); sat = 0; head = FNR ": " line
      next
    }
  }
  if (fence) infence = !infence
  if (open && (FNR in ok)) sat = 1
}
END { if (open && !sat) { print head; hits++ } exit (hits > 0) }
' "$work/req" "$1" || return $?
}

event="$(jq -r '.hook_event_name // ""' <<<"$input")" || fail "the payload has no readable hook_event_name"
case "$event:$tool_name" in
  PreToolUse:Write)
    jq -j '.tool_input.content // ""' <<<"$input" > "$work/file" || fail "the payload's content could not be read"
    when=before ;;
  PostToolUse:Edit | PostToolUse:MultiEdit)
    [ -f "$file_path" ] || exit 0
    cat -- "$file_path" > "$work/file" || fail "the edited file could not be read"
    when=after ;;
  *) exit 0 ;;
esac

hits="$(sections_judge "$work/file" "$require" "$level")"
case $? in 0) exit 0 ;; 1) ;; *) fail "the sections judge could not read the file" ;; esac

if [ "$when" = after ]; then
context="$(
  printf '[%s] %s: WARNING. %s\n' "$tag" "$name" "$message"
  printf 'Section(s) in %s with no line matching %s:\n%s\n' "$file_path" "$require" "$hits"
)"
jq -n --arg c "$context" '{hookSpecificOutput:{hookEventName:"PostToolUse",additionalContext:$c}}' || fail "jq could not build the warning"
exit 0
fi
{
  printf '[%s] %s: BLOCKED. %s\n' "$tag" "$name" "$message"
  printf 'Section(s) in %s with no line matching %s:\n%s\n' "$file_path" "$require" "$hits"
} >&2
exit 2

